# ── ПОМОЩНИКИ ПРОГРАММЫ ──────────────────────────────────────────

def get_active_users(ctx: ContextTypes.DEFAULT_TYPE) -> dict:
    return ctx.bot_data.setdefault("active_users", {})


def get_lesson_video(ctx, level: str, week: int) -> str | None:
    key = f"{level}_{week}"
    return ctx.bot_data.get("lesson_videos", {}).get(key)


def get_lesson_audio(ctx, level: str, week: int) -> str | None:
    key = f"{level}_{week}"
    return ctx.bot_data.get("lesson_audios", {}).get(key)


def _save_audio(ctx, level: str, week: int, value: str):
    ctx.bot_data.setdefault("lesson_audios", {})[f"{level}_{week}"] = value


async def send_week_lesson(bot, user_id: int, entry: dict, ctx=None):
    """Отправить урок недели конкретному пользователю."""
    level = entry["level"]
    week_idx = entry["week"] - 1
    lessons = PROGRAM.get(level, [])
    if week_idx >= len(lessons):
        return

    lesson = lessons[week_idx]
    name = entry.get("name", "Брат")
    title = lesson["title"]
    total = LEVEL_WEEKS[level]

    # Текст урока: для ВАКТ (уровень А) — берём текст по vakt_level участника
    raw_text = lesson["text"]
    if isinstance(raw_text, dict):
        vakt_level = entry.get("vakt_level", "А")
        text = raw_text.get(vakt_level, raw_text.get("А", ""))
    else:
        text = raw_text.replace("{name}", name.split()[0] if name else "Брат")

    # Задания: для ВАКТ — показываем только задания уровня участника
    raw_tasks = lesson["tasks"]
    if isinstance(raw_tasks, dict):
        if level == "А" and entry.get("vakt_level"):
            # ВАКТ: только задания выбранного уровня
            vakt_level = entry.get("vakt_level", "А")
            level_tasks = raw_tasks.get(vakt_level, [])
            tasks = "\n".join(f"  {t}" for t in level_tasks)
        else:
            # Другие уровни: показываем все три
            labels = {"А": "🌱 Уровень А", "Б": "📗 Уровень Б", "В": "📘 Уровень В"}
            tasks_parts = []
            for key, label in labels.items():
                lvl_tasks = raw_tasks.get(key, [])
                if lvl_tasks:
                    tasks_parts.append(
                        f"*{label}:*\n" + "\n".join(f"  {t}" for t in lvl_tasks)
                    )
            tasks = "\n\n".join(tasks_parts)
    else:
        tasks = "\n".join(f"  {t}" for t in raw_tasks)

    msg = (
        f"📅 *{title}*\n"
        f"_{LEVEL_NAMES[level]} · Неделя {entry['week']} из {total}_\n\n"
        f"{text}\n\n"
        f"*Задания на эту неделю:*\n{tasks}"
    )
    map_url = f"{MINIAPP_URL}?lvl={level}&wk={entry['week']}"

    # Видео для урока
    video_val = get_lesson_video(ctx, level, entry["week"]) if ctx else None
    audio_val = get_lesson_audio(ctx, level, entry["week"]) if ctx else None

    try:
        # 1. Видео
        if video_val:
            if video_val.startswith("http"):
                await bot.send_message(
                    chat_id=user_id,
                    text=f"🎬 *Видео-урок — Неделя {entry['week']}*\n\n{video_val}",
                    parse_mode="Markdown",
                    disable_web_page_preview=False,
                )
            else:
                await bot.send_video(
                    chat_id=user_id,
                    video=video_val,
                    caption=f"🎬 *Видео-урок — Неделя {entry['week']}*",
                    parse_mode="Markdown",
                )

        # 2. Голосовое (для тех кто слушает в дороге)
        if audio_val:
            await bot.send_voice(
                chat_id=user_id,
                voice=audio_val,
                caption="🎙 *Аудио-версия* — слушай где удобно",
                parse_mode="Markdown",
            )

        # Для ВАКТ (уровень А) — кнопка разблокировки следующей недели
        if level == "А":
            action_btn = InlineKeyboardButton("✅ Выполнил задания — открыть следующую неделю", callback_data="week_ack")
        else:
            action_btn = InlineKeyboardButton("✅ Понял, иду делать", callback_data="week_ack")

        await bot.send_message(
            chat_id=user_id,
            text=msg,
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("📱 Открыть карту пути", web_app=WebAppInfo(url=map_url))],
                [action_btn],
            ])
        )
    except Exception as e:
        logger.warning(f"Не удалось отправить урок пользователю {user_id}: {e}")


def _save_video(ctx, level: str, week: int, value: str):
    ctx.bot_data.setdefault("lesson_videos", {})[f"{level}_{week}"] = value


async def cmd_setaudio(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Куратор: отправь голосовое/аудио с подписью /setaudio Б 1"""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Только для кураторов.")
        return
    args = ctx.args
    if len(args) < 2:
        await update.message.reply_text(
            "🎙 *Как добавить аудио-версию урока:*\n\n"
            "Отправь голосовое сообщение или аудио-файл в бот,\n"
            "в подписи напиши: `/setaudio Б 1`\n\n"
            "Уровни: А (ВАКТ), Б (Сезон 1), В (Сезон 2), Г (Сезон 3)",
            parse_mode="Markdown"
        )
        return
    level = args[0].upper()
    try:
        week = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Неделя должна быть числом.")
        return
    # file_id из голосового или аудио
    if update.message.voice:
        file_id = update.message.voice.file_id
    elif update.message.audio:
        file_id = update.message.audio.file_id
    else:
        await update.message.reply_text("❌ Отправь голосовое сообщение или аудио-файл с этой подписью.")
        return
    _save_audio(ctx, level, week, file_id)
    await update.message.reply_text(
        f"✅ Аудио сохранено!\n\n"
        f"📍 Уровень *{level}*, Неделя *{week}*\n"
        f"🎙 Участники получат голосовое после видео",
        parse_mode="Markdown"
    )


async def cmd_listaudios(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Куратор: /listaudios — список всех аудио."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Только для кураторов.")
        return
    audios = ctx.bot_data.get("lesson_audios", {})
    if not audios:
        await update.message.reply_text("🎙 Аудио ещё не добавлены.\n\nИспользуй `/setaudio`", parse_mode="Markdown")
        return
    lines = ["🎙 *Аудио-уроки:*\n"]
    for key in sorted(audios.keys()):
        level, week = key.split("_")
        lines.append(f"• Уровень *{level}*, Неделя *{week}*: ✅")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def cmd_setvideo(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Куратор: два способа добавить видео-урок.

    Способ 1 — отправить видео с подписью:
        Отправь видео в бот, в подписи напиши: /setvideo Б 3

    Способ 2 — командой со ссылкой:
        /setvideo Б 3 https://disk.yandex.ru/i/XXXXX
    """
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Только для кураторов.")
        return
    args = ctx.args

    # Способ 1: команда пришла как подпись к видео
    if update.message.video and len(args) >= 2:
        level = args[0].upper()
        try:
            week = int(args[1])
        except ValueError:
            await update.message.reply_text("❌ Неделя должна быть числом.")
            return
        file_id = update.message.video.file_id
        _save_video(ctx, level, week, file_id)
        await update.message.reply_text(
            f"✅ Видео сохранено как файл Telegram\n\n"
            f"📍 Уровень *{level}*, Неделя *{week}*\n"
            f"🎬 Участники получат видео прямо в чат",
            parse_mode="Markdown"
        )
        return

    # Способ 2: команда со ссылкой /setvideo Б 3 https://...
    if len(args) < 2:
        await update.message.reply_text(
            "📹 *Два способа добавить видео-урок:*\n\n"
            "*Способ 1 — видео прямо в Telegram (рекомендуется):*\n"
            "Отправь видео в бот, в подписи напиши:\n"
            "`/setvideo Б 3`\n\n"
            "*Способ 2 — ссылка:*\n"
            "`/setvideo Б 3 https://disk.yandex.ru/i/XXXXX`\n\n"
            "Уровни: А (ВАКТ), Б (Сезон 1), В (Сезон 2), Г (Сезон 3)",
            parse_mode="Markdown"
        )
        return
    level = args[0].upper()
    try:
        week = int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Неделя должна быть числом.")
        return
    if len(args) < 3:
        await update.message.reply_text(
            "❌ Укажи ссылку или отправь видео с подписью `/setvideo Б 3`",
            parse_mode="Markdown"
        )
        return
    url = args[2]
    _save_video(ctx, level, week, url)
    await update.message.reply_text(
        f"✅ Видео-ссылка сохранена\n\n"
        f"📍 Уровень *{level}*, Неделя *{week}*\n"
        f"🔗 {url}",
        parse_mode="Markdown"
    )


async def cmd_listvideos(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Куратор: /listvideos — список всех видео."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Только для кураторов.")
        return
    videos = ctx.bot_data.get("lesson_videos", {})
    if not videos:
        await update.message.reply_text("📹 Видео ещё не добавлены.\n\nИспользуй `/setvideo`", parse_mode="Markdown")
        return
    lines = ["📹 *Видео-уроки:*\n"]
    for key in sorted(videos.keys()):
        level, week = key.split("_")
        lines.append(f"• Уровень *{level}*, Неделя *{week}*: {videos[key]}")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def handle_video_setvideo(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Куратор отправляет видео с подписью /setvideo Б 3 — сохраняем file_id."""
    caption = (update.message.caption or "").strip()
    parts = caption.split()
    # parts[0] = /setvideo, parts[1] = уровень, parts[2] = неделя
    if len(parts) < 3:
        await update.message.reply_text(
            "❌ Формат подписи: `/setvideo Б 3`",
            parse_mode="Markdown"
        )
        return
    level = parts[1].upper()
    try:
        week = int(parts[2])
    except ValueError:
        await update.message.reply_text("❌ Неделя должна быть числом, например: `/setvideo Б 3`", parse_mode="Markdown")
        return
    file_id = update.message.video.file_id
    _save_video(ctx, level, week, file_id)
    await update.message.reply_text(
        f"✅ Видео сохранено!\n\n"
        f"📍 Уровень *{level}*, Неделя *{week}*\n"
        f"🎬 Участники получат видео прямо в Telegram",
        parse_mode="Markdown"
    )


async def job_weekly_lesson(ctx: ContextTypes.DEFAULT_TYPE):
    """Запускается каждый понедельник в 9:00 — рассылает урок всем активным."""
    active = get_active_users(ctx)
    if not active:
        return
    sent = 0
    graduated: list = []
    for uid_str, entry in list(active.items()):
        uid   = int(uid_str)
        level = entry["level"]
        max_weeks = LEVEL_WEEKS.get(level, 8)

        # Уровень А (ВАКТ) — прогресс только через кнопку "Выполнил задания", не по расписанию
        if level == "А":
            continue

        # Участник завершил программу
        if entry["week"] > max_weeks:
            if not entry.get("completed_notified"):
                entry["completed_notified"] = True
                name = entry.get("name", "Участник")
                graduated.append((uid_str, name, level))
                try:
                    await ctx.bot.send_message(
                        chat_id=uid,
                        parse_mode="Markdown",
                        text=(
                            f"🎓 *МашаАллах, {name.split()[0]}!*\n\n"
                            f"Ты завершил *{LEVEL_NAMES[level]}*!\n\n"
                            f"Это большой шаг — ты дошёл до конца. "
                            f"Аллах видит каждое твоё усилие.\n\n"
                            f"🌿 _Твой сертификат готовится — куратор свяжется с тобой._"
                        )
                    )
                except Exception:
                    pass
            continue

        await send_week_lesson(ctx.bot, uid, entry, ctx)
        entry["week"] += 1
        sent += 1

    logger.info(f"Еженедельная рассылка: отправлено {sent} уроков, завершили: {len(graduated)}")

    # уведомить куратора
    lines = [f"📬 *Еженедельная рассылка завершена*\n\nОтправлено уроков: *{sent}*"]
    if graduated:
        lines.append("\n🎓 *Завершили программу:*")
        for uid_str, name, level in graduated:
            lines.append(f"  • {name} (`{uid_str}`) — {LEVEL_NAMES[level].split('·')[0].strip()}")
    for cid in CURATOR_IDS:
        try:
            await ctx.bot.send_message(
                chat_id=cid,
                text="\n".join(lines),
                parse_mode="Markdown"
            )
        except Exception:
            pass


async def cmd_activate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /activate <user_id> <уровень> [неделя]"""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return

    args = ctx.args
    if len(args) < 2:
        await update.message.reply_text(
            "Использование: `/activate <user_id> <А/Б/В> [неделя]`\n\n"
            "Например: `/activate 123456789 Б`\n"
            "Или с недели: `/activate 123456789 В 3`",
            parse_mode="Markdown"
        )
        return

    try:
        target_id = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Неверный user_id — должно быть число.")
        return

    level = args[1].upper()
    if level not in PROGRAM:
        await update.message.reply_text("❌ Уровень должен быть А, Б, В или Г.")
        return

    week = 1
    if len(args) >= 3:
        try:
            week = max(1, min(int(args[2]), LEVEL_WEEKS[level]))
        except ValueError:
            pass

    active = get_active_users(ctx)
    name = ctx.bot_data.get("user_names", {}).get(str(target_id), "Участник")

    active[str(target_id)] = {
        "level": level,
        "week": week,
        "name": name,
        "activated_at": datetime.now(timezone.utc).isoformat(),
    }

    # Запустить онбординг
    try:
        await run_onboarding(ctx.bot, target_id, name, level, week, ctx)
        participant_notified = "✅ Онбординг запущен"
    except Exception as e:
        participant_notified = f"⚠️ Не удалось запустить онбординг: {e}"

    # Автоназначение якорного брата/сестры
    paired = await auto_pair(ctx.bot, target_id, ctx)
    pair_status = "🤝 Якорный брат назначен автоматически" if paired else "⏳ Якорный брат — ждёт пары"

    await update.message.reply_text(
        f"✅ *Активировано*\n\n"
        f"👤 ID: `{target_id}`\n"
        f"📍 Уровень: *{level}* ({LEVEL_NAMES[level]})\n"
        f"📅 Начинает с недели: *{week}*\n"
        f"{participant_notified}\n"
        f"{pair_status}",
        parse_mode="Markdown"
    )


async def cmd_deactivate(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /deactivate <user_id>"""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return
    args = ctx.args
    if not args:
        await update.message.reply_text("Использование: `/deactivate <user_id>`", parse_mode="Markdown")
        return
    try:
        target_id = str(int(args[0]))
    except ValueError:
        await update.message.reply_text("❌ Неверный user_id.")
        return
    active = get_active_users(ctx)
    if target_id in active:
        del active[target_id]
        await update.message.reply_text(f"✅ Пользователь `{target_id}` деактивирован.", parse_mode="Markdown")
    else:
        await update.message.reply_text(f"Пользователь `{target_id}` не найден в программе.", parse_mode="Markdown")


async def cmd_analyze(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /analyze <user_id> — AI-анализ участника."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return
    if not _jarwas_client:
        await update.message.reply_text("❌ ANTHROPIC_API_KEY не задан.")
        return

    args = update.message.text.split()[1:]
    if not args:
        await update.message.reply_text(
            "Использование: `/analyze <user_id>`\n\n"
            "Например: `/analyze 123456789`",
            parse_mode="Markdown"
        )
        return
    try:
        target_uid = str(int(args[0]))
    except ValueError:
        await update.message.reply_text("❌ Неверный user_id.")
        return

    active  = get_active_users(ctx)
    entry   = active.get(target_uid)
    profile = ctx.bot_data.get("reg_profiles", {}).get(target_uid, {})

    # Принимаем и активных участников, и тех кто только прошёл диагностику
    if not entry and not profile:
        await update.message.reply_text(
            "❌ Пользователь не найден.\n\n"
            "Убедись что он писал боту — его ID должен быть в системе."
        )
        return

    # Собираем данные (active_users имеет приоритет, profile — fallback)
    name       = ctx.bot_data.get("user_names", {}).get(target_uid,
                    entry.get("name", profile.get("fio", "Участник")) if entry else profile.get("fio", "Участник"))
    level      = entry.get("level") if entry else ctx.bot_data.get("user_diag_level", {}).get(target_uid)
    week       = entry.get("week", 1) if entry else None
    occupation = profile.get("activity", "не указана")
    age        = profile.get("age", "не указан")
    status     = "активный участник" if entry else "прошёл диагностику, не активирован"

    # Дни молчания
    last_raw = (entry or {}).get("last_active", "")
    try:
        last_dt = datetime.fromisoformat(last_raw)
        if last_dt.tzinfo is None:
            last_dt = last_dt.replace(tzinfo=timezone.utc)
        silence_days = (datetime.now(timezone.utc) - last_dt).days
    except Exception:
        silence_days = 0

    # Мухасаба — последние 3 записи
    muh_logs = ctx.bot_data.get("muhasaba_logs", {}).get(target_uid, [])
    muh_text = ""
    for log in muh_logs[-3:]:
        answers = log.get("answers", [])
        row = " / ".join(str(a.get("a", ""))[:40] for a in answers if isinstance(a, dict))
        if row:
            muh_text += f"• {row}\n"
    muh_text = muh_text.strip() or "нет записей"

    await update.message.reply_text("🔍 Анализирую...")

    level_str = f"{level}, Неделя: {week}" if week else f"{level} (не активирован)"
    prompt = (
        f"Проанализируй участника программы IQ Barakah и дай куратору рекомендацию.\n\n"
        f"ДАННЫЕ УЧАСТНИКА:\n"
        f"Имя: {name}\n"
        f"Статус: {status}\n"
        f"Уровень диагностики: {level_str}\n"
        f"Деятельность: {occupation}\n"
        f"Возраст: {age}\n"
        f"Молчание в боте: {silence_days} дней\n\n"
        f"МУХАСАБА (последние записи):\n{muh_text}\n\n"
        f"Верни ТОЛЬКО валидный JSON без лишнего текста:\n"
        f'{{"risk": "low|medium|high", "summary": "...", "issue": "...", "action": "..."}}'
    )

    try:
        import json as _json
        response = _jarwas_client.messages.create(
            model="claude-sonnet-4-6",
            max_tokens=512,
            system=[{
                "type": "text",
                "text": (
                    "Ты — аналитик программы IQ Barakah. "
                    "Отвечаешь ТОЛЬКО валидным JSON без markdown-блоков и лишнего текста. "
                    "risk: low — всё хорошо, medium — нужно внимание, high — срочно связаться."
                ),
                "cache_control": {"type": "ephemeral"},
            }],
            messages=[{"role": "user", "content": prompt}],
        )
        raw = response.content[0].text.strip()
        # Убираем возможные ```json ... ``` обёртки
        if raw.startswith("```"):
            raw = raw.split("```")[1]
            if raw.startswith("json"):
                raw = raw[4:]
        data = _json.loads(raw.strip())

        risk = data.get("risk", "medium")
        RISK_EMOJI = {"low": "🟢", "medium": "🟡", "high": "🔴"}
        status_line = f"уровень {level} · неделя {week}" if week else f"диагностика: {level} · не активирован"
        await update.message.reply_text(
            f"🤖 *AI-анализ участника*\n\n"
            f"👤 {name} · {status_line}\n"
            f"{RISK_EMOJI.get(risk, '⚪')} Риск: *{risk.upper()}*\n\n"
            f"📊 {data.get('summary', '')}\n\n"
            f"⚠️ *Проблема:* {data.get('issue', '')}\n\n"
            f"✅ *Действие:* {data.get('action', '')}",
            parse_mode="Markdown",
        )
    except Exception as e:
        logger.warning(f"cmd_analyze error: {e}")
        await update.message.reply_text("❌ Ошибка AI-анализа. Попробуй позже.")


async def cmd_registered(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /registered — все кто когда-либо регистрировался."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return

    profiles  = ctx.bot_data.get("reg_profiles", {})
    names     = ctx.bot_data.get("user_names", {})
    active    = get_active_users(ctx)
    diag_lvls = ctx.bot_data.get("user_diag_level", {})

    if not profiles and not names:
        await update.message.reply_text("Никто ещё не регистрировался.")
        return

    all_uids = set(profiles.keys()) | set(names.keys())
    lines = [f"📋 *Все зарегистрированные ({len(all_uids)}):*\n"]

    for uid in sorted(all_uids):
        name       = names.get(uid, profiles.get(uid, {}).get("fio", "—"))
        diag_level = diag_lvls.get(uid, "—")
        is_active  = uid in active

        if is_active:
            entry = active[uid]
            status = f"✅ активен · {entry.get('level','?')} нед {entry.get('week','?')}"
        else:
            status = f"⏳ не активирован · диагностика: {diag_level}"

        lines.append(f"• `{uid}` — {name}\n  {status}")

    # Telegram ограничивает сообщение ~4096 символов — режем на части
    text = "\n".join(lines)
    for i in range(0, len(text), 4000):
        await update.message.reply_text(text[i:i+4000], parse_mode="Markdown")


