async def cmd_myprogram(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Пользователь смотрит свой прогресс."""
    uid = str(update.effective_user.id)
    active = get_active_users(ctx)
    entry = active.get(uid)
    if not entry:
        await update.message.reply_text(
            "У тебя пока нет активной программы.\n\n"
            "Пройди диагностику и свяжись с куратором для активации 🌿",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("🎯 Пройти диагностику", callback_data="start_diag")
            ]])
        )
        return

    level = entry["level"]
    week = entry["week"]
    max_w = LEVEL_WEEKS.get(level, 8)
    done = week - 1
    bar = "🟩" * done + "⬜️" * (max_w - done)
    pct = round(done / max_w * 100)

    lessons = PROGRAM.get(level, [])
    next_title = lessons[week - 1]["title"] if week <= max_w and (week - 1) < len(lessons) else "Программа завершена!"

    await update.message.reply_text(
        f"📊 *Твоя программа*\n\n"
        f"📍 {LEVEL_NAMES[level]}\n"
        f"📅 Неделя *{week}* из *{max_w}*\n"
        f"Progress: {bar} {pct}%\n\n"
        f"*Следующий урок:*\n_{next_title}_\n\n"
        f"_Каждый понедельник в 9:00 приходит новый урок_",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("📱 Открыть трекер", web_app=WebAppInfo(url=MINIAPP_URL))
        ]])
    )


async def cb_week_ack(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Нажата кнопка подтверждения недели.
    Для уровня А (ВАКТ): инкрементирует неделю и сразу открывает следующую.
    Для остальных: просто подтверждение, неделя идёт по расписанию."""
    query   = update.callback_query
    uid_str = str(update.effective_user.id)
    uid     = update.effective_user.id
    active  = get_active_users(ctx)
    entry   = active.get(uid_str)

    if not entry:
        await query.answer("Запись не найдена. Обратитесь к куратору.", show_alert=True)
        return

    level     = entry.get("level", "")
    max_weeks = LEVEL_WEEKS.get(level, 8)
    current_week = entry.get("week", 1)

    # Обновить last_active
    entry["last_active"] = datetime.now(timezone.utc).isoformat()

    # Записать подтверждение
    acks = ctx.bot_data.setdefault("week_acks", {})
    acks[uid_str] = {
        "week": current_week,
        "ts":   datetime.now(timezone.utc).isoformat(),
    }

    # ── ВАКТ (уровень А): разблокируем следующую неделю сразу ──────
    if level == "А":
        if current_week > max_weeks:
            await query.answer("Ты уже завершил всю программу! МашаАллах 🎓", show_alert=True)
            return

        await query.answer("МашаАллах! Открываем следующую неделю 🌿", show_alert=False)
        await query.edit_message_reply_markup(reply_markup=None)  # убираем кнопку

        # Проверка: последняя неделя завершена
        if current_week >= max_weeks:
            entry["week"] = max_weeks + 1
            entry["completed_notified"] = True
            letter = ctx.user_data.get("letter")
            first_name = entry.get('name', '').split()[0] or 'Брат'
            completion_text = (
                f"🎓 *МашаАллах, {first_name}!*\n\n"
                f"Ты завершил *{LEVEL_NAMES[level]}*!\n\n"
                "Аллах видит каждое твоё усилие. Это большой шаг вперёд.\n\n"
                "🌿 _Твой сертификат готовится — куратор свяжется с тобой._"
            )
            if letter and not ctx.user_data.get("letter_returned"):
                ctx.user_data["letter_returned"] = True
                completion_text += (
                    "\n\n✍️ *Твоё письмо себе — из самого начала пути:*\n\n"
                    f"_{letter}_\n\n"
                    "━━━━━━━━━━━━━━━\n"
                    "Посмотри как далеко ты прошёл. 🌿\n\nБаракАллах фикум! 🤲"
                )
            await ctx.bot.send_message(chat_id=uid, text=completion_text, parse_mode="Markdown")

            # Уpsell → Сезон 1 (только для ВАКТ, уровень А)
            upsell_text = (
                "━━━━━━━━━━━━━━━━\n"
                "📗 *Следующий шаг — IQ Barakah · Сезон 1*\n\n"
                f"{first_name}, ты заложил фундамент.\n"
                "Теперь пора строить — глубже и серьёзнее.\n\n"
                "*Сезон 1 · Основание* — 8 недель\n"
                "_«Кто ты есть» — психология, среда, фокус, цель_\n\n"
                "Еженедельные уроки прямо в боте + живые созвоны с куратором.\n\n"
                "🌿 _20% от оплаты → благотворительность_"
            )
            await ctx.bot.send_message(
                chat_id=uid,
                text=upsell_text,
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("📗 Начать Сезон 1 — оплатить", callback_data="pay_s1_full")],
                    [InlineKeyboardButton("💬 Узнать подробнее у куратора", url=SITE)],
                ])
            )
            return

        # Открываем следующую неделю
        entry["week"] = current_week + 1
        await ctx.bot.send_message(
            chat_id=uid,
            parse_mode="Markdown",
            text=(
                f"✅ *Неделя {current_week} выполнена!*\n\n"
                f"БаракАллах фикум! Открываем *Неделю {current_week + 1}* 👇"
            )
        )
        await send_week_lesson(ctx.bot, uid, entry, ctx)

    # ── Остальные уровни: просто подтверждение ──────────────────────
    else:
        await query.answer("МашаАллах! Баракат в каждом шаге 🌿", show_alert=False)

        # Проверить завершение программы — вернуть письмо себе
        if current_week >= max_weeks:
            letter = ctx.user_data.get("letter")
            if letter and not ctx.user_data.get("letter_returned"):
                ctx.user_data["letter_returned"] = True
                try:
                    await ctx.bot.send_message(
                        chat_id=uid,
                        parse_mode="Markdown",
                        text=(
                            "✍️ *Твоё письмо себе — из самого начала пути:*\n\n"
                            f"_{letter}_\n\n"
                            "━━━━━━━━━━━━━━━\n"
                            "Ты написал это когда только начинал.\n"
                            "Посмотри как далеко ты прошёл. 🌿\n\n"
                            "БаракАллах фикум! 🤲"
                        )
                    )
                except Exception as e:
                    logger.warning(f"letter_return → {uid}: {e}")


async def cb_vakt_level(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Участник выбирает уровень ВАКТ (А/Б/В) или идёт на диагностику."""
    query = update.callback_query
    await query.answer()
    uid = str(update.effective_user.id)
    level_choice = query.data.replace("vakt_level_", "")

    # Направляем на существующую диагностику
    if level_choice == "diag":
        await query.edit_message_text(
            "🎯 *Пройди диагностику* — и мы сами определим твой уровень.\n\n"
            "Нажми кнопку ниже 👇",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("🎯 Начать диагностику", callback_data="start_diag")
            ]])
        )
        return

    # Сохранить выбранный уровень
    entry = ctx.bot_data.get("active_users", {}).get(uid)
    if entry:
        entry["vakt_level"] = level_choice

    labels = {"А": "🌱 Уровень А", "Б": "📗 Уровень Б", "В": "📘 Уровень В"}
    await query.edit_message_text(
        f"✅ Выбран *{labels.get(level_choice, level_choice)}*\n\n"
        f"БисмиЛлях! Вот твой первый урок 👇",
        parse_mode="Markdown"
    )
    if entry:
        await send_week_lesson(ctx.bot, update.effective_user.id, entry, ctx)


