async def cmd_start(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    user = update.effective_user
    uid = str(user.id)

    # Дедупликация: игнорируем если /start пришёл повторно в течение 3 секунд
    now_ts = datetime.now(timezone.utc).timestamp()
    if now_ts - ctx.user_data.get("_last_start_ts", 0) < 3:
        return ConversationHandler.END
    ctx.user_data["_last_start_ts"] = now_ts

    # Сбрасываем незавершённые сессии диагностики/мухасабы
    ctx.user_data.pop("_diag_active", None)
    ctx.user_data.pop("_diag_step", None)
    ctx.user_data.pop("_muh_active", None)

    ctx.bot_data.setdefault("user_usernames", {})[uid] = user.username

    # Если уже знаком — сразу меню (но не если только что сделал /resetme)
    force_new  = ctx.user_data.pop("_force_new", False)
    profiles   = ctx.bot_data.get("reg_profiles", {})
    diag_lvls  = ctx.bot_data.get("user_diag_level", {})
    if not force_new and (uid in profiles or uid in diag_lvls):
        name = user.first_name or "друг"
        await update.message.reply_text(
            f"*Ассаляму алейкум, {name}!* 🌙\n\nДобро пожаловать обратно.",
            parse_mode="Markdown",
            reply_markup=MAIN_MENU
        )
        return ConversationHandler.END

    # Новый пользователь — тёплый онбординг (3 шага перед регистрацией)
    ctx.user_data.clear()
    ctx.user_data["scores"] = []
    ctx.user_data["_diag_active"] = True
    text = (
        "Ассаляму алейкум, брат / сестра! 🌿\n\n"
        "Если ты здесь — значит, что-то в твоих днях идёт не так. Знакомо: "
        "бежишь с утра до ночи, тушишь один пожар за другим, а вечером "
        "падаешь без сил — и внутри пусто? Будто жизнь идёт, а ты в ней "
        "не водитель, а пассажир.\n\n"
        "Так живёт почти каждый. И это не лень и не слабость — просто "
        "никто не показал, как по-другому.\n\n"
        "Здесь не будет давления, упрёков и «соберись». Будет другое — "
        "спокойные маленькие шаги, которые возвращают тебе твоё время "
        "и твои силы. В твоём темпе, без надрыва.\n\n"
        "Меня зовут Джарвас, и я буду рядом на этом пути.\n\n"
        "Готов / готова сделать первый шаг?"
    )
    keyboard = [[InlineKeyboardButton("Готов / Готова", callback_data="onboard_ready")]]
    await update.message.reply_text(
        text, reply_markup=InlineKeyboardMarkup(keyboard), parse_mode="HTML"
    )
    return ONBOARD_READY


async def reg_got_consent(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    uid = str(update.effective_user.id)
    ctx.bot_data.setdefault("pd_consents", {})[uid] = {
        "agreed": True,
        "date": datetime.now(timezone.utc).isoformat(),
    }
    await query.edit_message_text(
        "*Вопрос 1 из 5*\n\nВаше ФИО _(Фамилия Имя Отчество)_:",
        parse_mode="Markdown"
    )
    return REG_FIO


async def reg_got_fio(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    fio = update.message.text.strip()
    if len(fio) < 3:
        await update.message.reply_text("Пожалуйста, введите полное ФИО (Фамилия Имя Отчество):")
        return REG_FIO
    ctx.user_data["reg_fio"] = fio
    await update.message.reply_text(
        "*Вопрос 2 из 5*\n\nДата рождения _(например: 15.03.1990)_:",
        parse_mode="Markdown"
    )
    return REG_BIRTHDATE


async def reg_got_birthdate(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    text = update.message.text.strip()
    # Проверка формата ДД.ММ.ГГГГ
    import re
    if not re.match(r"^\d{1,2}\.\d{1,2}\.\d{4}$", text):
        await update.message.reply_text(
            "⚠️ Введите дату в формате ДД.ММ.ГГГГ _(например: 15.03.1990)_:",
            parse_mode="Markdown"
        )
        return REG_BIRTHDATE
    ctx.user_data["reg_birthdate"] = text
    await update.message.reply_text(
        "*Вопрос 3 из 5*\n\nВаш пол:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("🧔 Мужской", callback_data="reg_gender_m"),
            InlineKeyboardButton("🧕 Женский",  callback_data="reg_gender_f"),
        ]])
    )
    return REG_GENDER


async def reg_got_gender(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    is_female = query.data == "reg_gender_f"
    ctx.user_data["reg_is_female"] = is_female
    uid = str(update.effective_user.id)
    ctx.bot_data.setdefault("user_genders", {})[uid] = is_female

    await query.edit_message_text(
        "*Вопрос 4 из 5*\n\nВид деятельности:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("💼 Предприниматель",   callback_data="reg_act_entrepreneur")],
            [InlineKeyboardButton("🧑‍💻 Самозанятый",      callback_data="reg_act_freelance")],
            [InlineKeyboardButton("👔 Наёмный сотрудник", callback_data="reg_act_employee")],
            [InlineKeyboardButton("🎓 Студент",            callback_data="reg_act_student")],
            [InlineKeyboardButton("🏠 Другое",             callback_data="reg_act_other")],
        ])
    )
    return REG_ACTIVITY


async def reg_got_activity(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    query = update.callback_query
    await query.answer()
    ctx.user_data["reg_activity"] = query.data.replace("reg_act_", "")
    await query.edit_message_text(
        "*Вопрос 5 из 5*\n\n📞 Ваш номер телефона:\n\n"
        "_Нужен для поддержания связи с вами. Формат: +7XXXXXXXXXX_",
        parse_mode="Markdown"
    )
    return REG_PHONE


async def reg_got_phone(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    import re
    phone = update.message.text.strip().replace(" ", "").replace("-", "")
    uid = str(update.effective_user.id)
    is_female = ctx.user_data.get("reg_is_female", False)
    fio = ctx.user_data.get("reg_fio", "")

    if not re.match(r"^[\+7\d][\d]{9,14}$", phone):
        await update.message.reply_text(
            "⚠️ Введите корректный номер телефона (например: +79001234567):"
        )
        return REG_PHONE

    profile = {
        "fio":       fio,
        "birthdate": ctx.user_data.get("reg_birthdate", ""),
        "activity":  ctx.user_data.get("reg_activity", ""),
        "gender":    "f" if is_female else "m",
        "phone":     phone,
    }
    ctx.bot_data.setdefault("reg_profiles", {})[uid] = profile
    ctx.bot_data.setdefault("user_names",   {})[uid] = fio
    ctx.bot_data.setdefault("user_phones",  {})[uid] = phone

    word = "Сестра" if is_female else "Брат"
    first_name = fio.split()[1] if len(fio.split()) > 1 else fio.split()[0]
    await update.message.reply_text(
        f"✅ *{word} {first_name}, добро пожаловать!*\n\n"
        "Вы на пороге системы, которая изменит ваше отношение ко времени, делам и внутреннему состоянию. "
        "Здесь начинается путь к жизни с баракатом и осознанной эффективностью.\n\n"
        "За 24 недели вы получите: ясность в целях, дисциплину и настоящий баракат — "
        "когда время и энергия работают на вас.\n\n"
        "Используйте меню ниже 👇",
        parse_mode="Markdown",
        reply_markup=MAIN_MENU
    )
    return ConversationHandler.END


async def cmd_diag(update: Update, ctx: ContextTypes.DEFAULT_TYPE) -> int:
    """Старт диагностики — из кнопки или /diag"""
    uid = str(update.effective_user.id)

    # Если пользователь уже зарегистрирован — не спрашиваем данные повторно
    saved_name = ctx.bot_data.get("user_names", {}).get(uid)
    if saved_name:
        is_female = ctx.bot_data.get("user_genders", {}).get(uid, False)
        ctx.user_data["name"] = saved_name
        ctx.user_data["is_female"] = is_female
        ctx.user_data["scores"] = []
        ctx.user_data["_diag_active"] = True
        name_first = saved_name.split()[0]
        brat = "сестра" if is_female else "брат"
        await update.message.reply_text(
            f"🌿 {brat.capitalize()} *{name_first}*, снова на диагностику!\n\n"
            "_8 вопросов — честно посмотрим, где ты сейчас._",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("🎯 Начать диагностику", callback_data="begin_diag")
            ]])
        )
        return READY

    # Новый пользователь — собираем данные
    ctx.user_data.clear()
    ctx.user_data["scores"] = []
    ctx.user_data["_diag_active"] = True
    await update.message.reply_text(
        "🌿 *Добро пожаловать в IQ Barakah*\n\n"
        "Это место, где наводят порядок — в душе, в делах, в семье.\n"
        "Без лишних слов. По шагам. С поддержкой.\n\n"
        "Сначала познакомимся 🤝\n\n"
        "Как тебя зовут? _(Имя и фамилия)_",
        parse_mode="Markdown"
    )
    return NAME


