def tariff_keyboard(tariff_id: str) -> InlineKeyboardMarkup:
    """Кнопки под карточкой тарифа."""
    price = next(t["price"] for t in TARIFFS if t["id"] == tariff_id)
    return InlineKeyboardMarkup([
        [InlineKeyboardButton(f"💳 Оплатить {price:,} ₽".replace(",", " "), callback_data=f"pay_{tariff_id}")],
        [InlineKeyboardButton("◀️ Все тарифы", callback_data="show_tariffs")],
    ])


async def cmd_payment(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Список всех тарифов с кнопками оплаты."""
    rows = []
    for t in TARIFFS:
        rows.append([InlineKeyboardButton(
            f"{t['name']} — {t['price']:,} ₽".replace(",", " "),
            callback_data=f"tariff_{t['id']}"
        )])
    rows.append([InlineKeyboardButton("🎯 Сначала пройти диагностику", callback_data="start_diag")])

    msg = update.message if update.message else update.callback_query.message
    await msg.reply_text(
        "💳 *Выберите тариф*\n\n"
        "🌿 _20% от каждой оплаты → благотворительность_\n\n"
        "Нажмите на тариф чтобы узнать подробнее и оплатить:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(rows)
    )


async def cb_show_tariff(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Карточка конкретного тарифа."""
    query = update.callback_query
    await query.answer()
    tariff_id = query.data.replace("tariff_", "")
    t = next((x for x in TARIFFS if x["id"] == tariff_id), None)
    if not t:
        return
    await query.edit_message_text(
        t["details"],
        parse_mode="Markdown",
        reply_markup=tariff_keyboard(tariff_id)
    )


async def cb_show_tariffs(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Вернуться к списку тарифов."""
    query = update.callback_query
    await query.answer()
    rows = []
    for t in TARIFFS:
        rows.append([InlineKeyboardButton(
            f"{t['name']} — {t['price']:,} ₽".replace(",", " "),
            callback_data=f"tariff_{t['id']}"
        )])
    rows.append([InlineKeyboardButton("🎯 Сначала пройти диагностику", callback_data="start_diag")])
    await query.edit_message_text(
        "💳 *Выберите тариф*\n\n"
        "🌿 _20% от каждой оплаты → благотворительность_\n\n"
        "Нажмите на тариф чтобы узнать подробнее и оплатить:",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup(rows)
    )


async def cb_pay(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Обработка нажатия 'Оплатить' — ЮКасса."""
    query = update.callback_query
    await query.answer()
    tariff_id = query.data.replace("pay_", "")
    t = next((x for x in TARIFFS if x["id"] == tariff_id), None)
    if not t:
        return

    user = update.effective_user
    username = f"@{user.username}" if user.username else f"ID {user.id}"
    price_rub = f"{t['price']:,}".replace(",", " ")

    # Оплата через ЮКасса
    try:
        idempotency_key = str(uuid.uuid4())
        uid = str(user.id)
        user_email = ctx.bot_data.get("user_emails", {}).get(uid, "")

        payment_data = {
            "amount": {"value": f"{t['price']}.00", "currency": "RUB"},
            "confirmation": {"type": "redirect", "return_url": "https://t.me/iqbarakah_bot"},
            "capture": True,
            "description": f"{t['name']} — IQ Barakah",
            "metadata": {"tariff_id": tariff_id, "user_id": uid},
        }

        # Добавляем чек если есть email (54-ФЗ)
        if user_email:
            payment_data["receipt"] = {
                "customer": {"email": user_email},
                "items": [{
                    "description": t["name"],
                    "quantity": "1.00",
                    "amount": {"value": f"{t['price']}.00", "currency": "RUB"},
                    "vat_code": 1,  # 1 = без НДС
                    "payment_mode": "full_payment",
                    "payment_subject": "service",
                }]
            }
        else:
            # Email не найден — запрашиваем прямо здесь
            ctx.user_data["pending_tariff"] = tariff_id
            ctx.user_data["awaiting_pay_email"] = True
            await query.edit_message_text(
                "📧 *Для получения чека нужен ваш email.*\n\n"
                "Пожалуйста, введите ваш email (например: ivan@mail.ru):",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton("◀️ Назад", callback_data="show_tariffs")
                ]])
            )
            return

        payment = YooPayment.create(payment_data, idempotency_key)

        pay_url = payment.confirmation.confirmation_url
        payment_id = payment.id

        ctx.bot_data.setdefault("pending_payments", {})[str(user.id)] = {
            "payment_id": payment_id,
            "tariff_id": tariff_id,
            "tariff_name": t["name"],
            "price": t["price"],
        }

        for cid in CURATOR_IDS:
            try:
                await ctx.bot.send_message(
                    chat_id=cid, parse_mode="Markdown",
                    text=(
                        f"💳 *Создан счёт на оплату*\n\n"
                        f"👤 {user.full_name} ({username})\n"
                        f"📦 Тариф: *{t['name']}*\n"
                        f"💰 Сумма: *{price_rub} ₽*\n"
                        f"🔑 ID: `{payment_id}`"
                    )
                )
            except Exception:
                pass

        await query.edit_message_text(
            f"💳 *{t['name']}*\n\n"
            f"💰 Сумма: *{price_rub} ₽*\n\n"
            f"Нажмите кнопку ниже для оплаты. После оплаты нажмите «✅ Я оплатил».\n\n"
            f"_Нажимая «Перейти к оплате», вы принимаете условия [публичной оферты](https://iq-barakah.ru/oferta.html)._",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("💳 Перейти к оплате", url=pay_url)],
                [InlineKeyboardButton("✅ Я оплатил", callback_data=f"check_pay_{tariff_id}")],
                [InlineKeyboardButton("◀️ Назад", callback_data="show_tariffs")],
            ])
        )
        return

    except Exception as e:
        logger.error(f"YooKassa error: {e}")
        await query.edit_message_text(
            f"⚠️ Ошибка создания платежа. Свяжитесь с куратором.\n\n(Детали: {e})",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("💬 Написать куратору", callback_data="contact_curator")
            ]])
        )
        return

    # Fallback — ручная оплата если ЮКасса не настроена
    for cid in CURATOR_IDS:
        try:
            await ctx.bot.send_message(
                chat_id=cid, parse_mode="Markdown",
                text=(
                    f"💳 *Запрос на оплату*\n\n"
                    f"👤 {user.full_name} ({username})\n"
                    f"📦 Тариф: *{t['name']}*\n"
                    f"💰 Сумма: *{price_rub} ₽*\n\n"
                    f"Свяжитесь с участником для выставления счёта."
                )
            )
        except Exception:
            pass

    await query.edit_message_text(
        f"✅ *Заявка принята!*\n\n"
        f"📦 Тариф: *{t['name']}*\n"
        f"💰 Сумма: *{price_rub} ₽*\n\n"
        f"Куратор свяжется с тобой в течение нескольких часов.\n\n"
        f"📧 info@iqbarakah.ru\n"
        f"🌿 _Баракат в каждом шаге_",
        parse_mode="Markdown",
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("◀️ Все тарифы", callback_data="show_tariffs")],
        ])
    )


