async def cmd_setemail(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Сохранить email пользователя для чеков"""
    uid = str(update.effective_user.id)
    args = ctx.args
    if not args:
        await update.message.reply_text(
            "Введите: `/setemail ваш@email.ru`",
            parse_mode="Markdown"
        )
        return
    email = args[0].strip()
    if "@" not in email or "." not in email:
        await update.message.reply_text("⚠️ Некорректный email. Пример: `/setemail ivan@mail.ru`", parse_mode="Markdown")
        return
    ctx.bot_data.setdefault("user_emails", {})[uid] = email
    # Обновить в профиле тоже
    if uid in ctx.bot_data.get("reg_profiles", {}):
        ctx.bot_data["reg_profiles"][uid]["email"] = email
    await update.message.reply_text(
        f"✅ Email `{email}` сохранён. Теперь можете оплатить тариф.",
        parse_mode="Markdown"
    )
    # Если был отложенный тариф — напомнить
    pending = ctx.user_data.get("pending_tariff")
    if pending:
        t = next((x for x in TARIFFS if x["id"] == pending), None)
        if t:
            await update.message.reply_text(
                f"💳 Продолжить оплату *{t['name']}*?",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(f"Оплатить {t['price']:,} ₽".replace(",", " "), callback_data=f"pay_{pending}")
                ]])
            )


async def pay_email_handler(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Ловит email введённый пользователем перед оплатой."""
    if not ctx.user_data.get("awaiting_pay_email"):
        return  # не ждём email — пропускаем
    import re
    email = update.message.text.strip()
    if not re.match(r"^[^\s@]+@[^\s@]+$", email):
        await update.message.reply_text(
            "⚠️ Некорректный email. Введите снова (например: ivan@mail.ru):"
        )
        raise ApplicationHandlerStop  # не пропускаем в другие обработчики
    uid = str(update.effective_user.id)
    ctx.bot_data.setdefault("user_emails", {})[uid] = email
    if uid in ctx.bot_data.get("reg_profiles", {}):
        ctx.bot_data["reg_profiles"][uid]["email"] = email
    ctx.user_data.pop("awaiting_pay_email", None)

    pending = ctx.user_data.get("pending_tariff")
    if pending:
        t = next((x for x in TARIFFS if x["id"] == pending), None)
        if t:
            await update.message.reply_text(
                f"✅ Email сохранён!\n\n💳 Продолжить оплату *{t['name']}* — {t['price']} ₽?",
                parse_mode="Markdown",
                reply_markup=InlineKeyboardMarkup([[
                    InlineKeyboardButton(f"💳 Оплатить {t['price']} ₽", callback_data=f"pay_{pending}")
                ]])
            )
    else:
        await update.message.reply_text(f"✅ Email сохранён.")
    raise ApplicationHandlerStop  # блокируем попадание в диагностику или рег. опросник


async def cmd_resetme(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Сброс регистрации — только для куратора/тестирования"""
    uid = str(update.effective_user.id)
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔ Команда недоступна.")
        return
    # Чистим все данные пользователя из bot_data
    ctx.bot_data.get("reg_profiles",    {}).pop(uid, None)
    ctx.bot_data.get("pd_consents",     {}).pop(uid, None)
    ctx.bot_data.get("user_emails",     {}).pop(uid, None)
    ctx.bot_data.get("user_phones",     {}).pop(uid, None)
    ctx.bot_data.get("user_diag_level", {}).pop(uid, None)
    ctx.bot_data.get("active_users",    {}).pop(uid, None)
    ctx.bot_data.get("user_names",      {}).pop(uid, None)
    ctx.bot_data.get("user_genders",    {}).pop(uid, None)
    # Ставим флаг — cmd_start покажет экран нового пользователя даже если pickle ещё не сбросился
    ctx.user_data.clear()
    ctx.user_data["_force_new"] = True
    await update.message.reply_text(
        "✅ Готово — бот тебя забыл.\n\nНапиши /start — увидишь экран нового пользователя."
    )


