#  ЭТАП 4 — ЯКОРНЫЙ БРАТ
# ══════════════════════════════════════════════════════════════════

def get_pairs(ctx: ContextTypes.DEFAULT_TYPE) -> dict:
    """bot_data['pairs'] = {uid: partner_uid, ...} — двусторонний словарь."""
    return ctx.bot_data.setdefault("pairs", {})


async def auto_pair(bot, uid: int, ctx) -> bool:
    """Автоматически ищет свободного партнёра того же пола и уровня.
    Парит ТОЛЬКО если пол известен у обоих и совпадает. Возвращает True если пара найдена."""
    uid_str = str(uid)
    pairs = get_pairs(ctx)
    if uid_str in pairs:
        return False  # уже есть пара

    genders   = ctx.bot_data.get("user_genders", {})
    active    = get_active_users(ctx)
    names     = ctx.bot_data.get("user_names", {})
    usernames = ctx.bot_data.get("user_usernames", {})

    is_female = genders.get(uid_str)
    if is_female is None:
        return False  # пол неизвестен — не паровать

    my_level = active.get(uid_str, {}).get("level")

    # Ищем активного участника без пары: строго тот же пол + тот же уровень
    partner_id = None
    for pid_str, entry in active.items():
        if pid_str == uid_str:
            continue
        if pid_str in pairs:
            continue
        p_gender = genders.get(pid_str)
        if p_gender is None or p_gender != is_female:
            continue
        if my_level and entry.get("level") != my_level:
            continue
        partner_id = int(pid_str)
        break

    if not partner_id:
        return False

    # Назначаем пару двусторонне
    pairs[uid_str] = partner_id
    pairs[str(partner_id)] = uid

    name1    = names.get(uid_str, "Участник")
    name2    = names.get(str(partner_id), "Участник")
    link1    = _user_link(uid, name1, usernames.get(uid_str))
    link2    = _user_link(partner_id, name2, usernames.get(str(partner_id)))
    word     = lambda f: "якорная сестра" if f else "якорный брат"

    msg = (
        "🤝 *{title} назначен{a}!*\n\n"
        "👤 {link}\n\n"
        "📋 *Правила:*\n"
        "• Пиши каждую пятницу — как дела, как практики\n"
        "• Делай дуа за него/неё по имени\n"
        "• Поддерживай — не осуждай\n\n"
        "🌿 _Баракат приходит через связь_"
    )

    await bot.send_message(
        uid,
        msg.format(
            title=word(is_female).capitalize(),
            a="а" if is_female else "",
            link=link2
        ),
        parse_mode="Markdown",
        disable_web_page_preview=True
    )
    p_female = genders.get(str(partner_id))
    await bot.send_message(
        partner_id,
        msg.format(
            title=word(p_female).capitalize(),
            a="а" if p_female else "",
            link=link1
        ),
        parse_mode="Markdown",
        disable_web_page_preview=True
    )
    return True


def _user_link(uid: int, name: str, username: str | None) -> str:
    if username:
        return f"[{name}](https://t.me/{username})"
    return f"[{name}](tg://user?id={uid})"


async def cmd_pair(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /pair <uid1> <uid2> — создать пару."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return

    args = ctx.args
    if len(args) < 2:
        await update.message.reply_text(
            "Использование: `/pair <user_id_1> <user_id_2>`\n\n"
            "Пример: `/pair 111222333 444555666`",
            parse_mode="Markdown"
        )
        return

    try:
        uid1, uid2 = int(args[0]), int(args[1])
    except ValueError:
        await update.message.reply_text("❌ Оба аргумента должны быть числами (user_id).")
        return

    if uid1 == uid2:
        await update.message.reply_text("❌ Нельзя соединить пользователя с самим собой.")
        return

    pairs = get_pairs(ctx)
    names = ctx.bot_data.get("user_names", {})
    usernames = ctx.bot_data.get("user_usernames", {})

    name1 = names.get(str(uid1), f"Участник {uid1}")
    name2 = names.get(str(uid2), f"Участник {uid2}")
    un1   = usernames.get(str(uid1))
    un2   = usernames.get(str(uid2))

    # Разорвать старые пары если были
    for uid, partner in list(pairs.items()):
        if int(uid) in (uid1, uid2) or partner in (uid1, uid2):
            old_partner = partner if int(uid) in (uid1, uid2) else int(uid)
            pairs.pop(uid, None)
            pairs.pop(str(old_partner), None)

    # Создать новую пару (двусторонняя)
    pairs[str(uid1)] = uid2
    pairs[str(uid2)] = uid1

    link1 = _user_link(uid1, name1, un1)
    link2 = _user_link(uid2, name2, un2)

    msg1 = (
        "🤝 *Твой якорный брат назначен!*\n\n"
        f"Познакомься — это {link2}\n\n"
        "Якорный брат — это тот, кто поддерживает тебя на пути. "
        "Вы отвечаете друг другу за выполнение заданий каждую неделю.\n\n"
        "📋 *Правила якорного брата:*\n"
        "• Спрашивай его каждую пятницу: «Как прошла неделя?»\n"
        "• Честно отвечай когда спрашивают тебя\n"
        "• Делай дуа за него каждый день\n"
        "• Не осуждай — поддерживай\n\n"
        "🌿 _Напиши ему сейчас — познакомьтесь!_"
    )
    msg2 = (
        "🤝 *Твой якорный брат назначен!*\n\n"
        f"Познакомься — это {link1}\n\n"
        "Якорный брат — это тот, кто поддерживает тебя на пути. "
        "Вы отвечаете друг другу за выполнение заданий каждую неделю.\n\n"
        "📋 *Правила якорного брата:*\n"
        "• Спрашивай его каждую пятницу: «Как прошла неделя?»\n"
        "• Честно отвечай когда спрашивают тебя\n"
        "• Делай дуа за него каждый день\n"
        "• Не осуждай — поддерживай\n\n"
        "🌿 _Напиши ему сейчас — познакомьтесь!_"
    )

    notify_ok = []
    for uid, msg in ((uid1, msg1), (uid2, msg2)):
        try:
            await ctx.bot.send_message(chat_id=uid, text=msg,
                                       parse_mode="Markdown",
                                       disable_web_page_preview=True)
            notify_ok.append(str(uid))
        except Exception as e:
            logger.warning(f"Пара: не удалось уведомить {uid}: {e}")

    await update.message.reply_text(
        f"✅ *Пара создана*\n\n"
        f"🤝 {link1}  ↔  {link2}\n\n"
        f"Уведомлены: {', '.join(notify_ok) or '—'}",
        parse_mode="Markdown",
        disable_web_page_preview=True
    )


async def cmd_unpair(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /unpair <uid> — разорвать пару."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return
    args = ctx.args
    if not args:
        await update.message.reply_text("Использование: `/unpair <user_id>`", parse_mode="Markdown")
        return
    try:
        uid = int(args[0])
    except ValueError:
        await update.message.reply_text("❌ Неверный user_id.")
        return

    pairs = get_pairs(ctx)
    partner_id = pairs.pop(str(uid), None)
    if partner_id:
        pairs.pop(str(partner_id), None)
        await update.message.reply_text(
            f"✅ Пара `{uid}` ↔ `{partner_id}` разорвана.", parse_mode="Markdown"
        )
        for cid in (uid, partner_id):
            try:
                await ctx.bot.send_message(
                    chat_id=cid,
                    text="ℹ️ Твоя пара якорного брата была изменена куратором. "
                         "Скоро тебе назначат нового — оставайся на пути! 🌿"
                )
            except Exception:
                pass
    else:
        await update.message.reply_text(f"Пользователь `{uid}` не в паре.", parse_mode="Markdown")


async def cmd_mybrother(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Участник смотрит кто его якорный брат."""
    uid = str(update.effective_user.id)
    # Сохранить username при каждом вызове
    user = update.effective_user
    ctx.bot_data.setdefault("user_usernames", {})[uid] = user.username

    pairs = get_pairs(ctx)
    partner_id = pairs.get(uid)

    if not partner_id:
        await update.message.reply_text(
            "🤝 *Якорный брат*\n\n"
            "У тебя пока нет якорного брата.\n\n"
            "Якорный брат назначается куратором после начала программы. "
            "Это участник который идёт рядом с тобой и поддерживает тебя каждую неделю.\n\n"
            "💬 Свяжись с куратором чтобы узнать когда будет назначен.",
            parse_mode="Markdown",
            reply_markup=InlineKeyboardMarkup([[
                InlineKeyboardButton("💬 Написать куратору", callback_data="contact_curator")
            ]])
        )
        return

    names     = ctx.bot_data.get("user_names", {})
    usernames = ctx.bot_data.get("user_usernames", {})
    p_name    = names.get(str(partner_id), f"Участник {partner_id}")
    p_un      = usernames.get(str(partner_id))
    link      = _user_link(partner_id, p_name, p_un)

    await update.message.reply_text(
        f"🤝 *Твой якорный брат*\n\n"
        f"👤 {link}\n\n"
        f"📋 *Напомни себе:*\n"
        f"• Пиши ему каждую пятницу\n"
        f"• Делай дуа за него по имени\n"
        f"• Поддерживай — не осуждай\n\n"
        f"🌿 _Баракат приходит через связь_",
        parse_mode="Markdown",
        disable_web_page_preview=True,
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("✉️ Написать ему", url=f"tg://user?id={partner_id}")
        ]])
    )


async def cmd_pairs(update: Update, ctx: ContextTypes.DEFAULT_TYPE):
    """Только для кураторов. /pairs — список всех пар."""
    if update.effective_user.id not in CURATOR_IDS:
        await update.message.reply_text("⛔️ Команда только для кураторов.")
        return
    pairs = get_pairs(ctx)
    names = ctx.bot_data.get("user_names", {})
    if not pairs:
        await update.message.reply_text("Нет активных пар.")
        return
    seen = set()
    lines = ["👥 *Активные пары якорных братьев:*\n"]
    for uid, partner in pairs.items():
        key = tuple(sorted([uid, str(partner)]))
        if key in seen:
            continue
        seen.add(key)
        n1 = names.get(uid, f"ID {uid}")
        n2 = names.get(str(partner), f"ID {partner}")
        lines.append(f"• {n1} (`{uid}`)  🤝  {n2} (`{partner}`)")
    await update.message.reply_text("\n".join(lines), parse_mode="Markdown")


async def job_friday_checkin(ctx: ContextTypes.DEFAULT_TYPE):
    """Каждую пятницу в 10:00 МСК — напоминание написать якорному брату."""
    pairs = get_pairs(ctx)
    seen = set()
    count = 0
    for uid_str, partner_id in pairs.items():
        key = tuple(sorted([uid_str, str(partner_id)]))
        if key in seen:
            continue
        seen.add(key)
        names = ctx.bot_data.get("user_names", {})
        p_name = names.get(str(partner_id), "якорному брату").split()[0]
        for cid, pid, pn in ((int(uid_str), partner_id, p_name),
                              (partner_id, int(uid_str), names.get(uid_str, "якорному брату").split()[0])):
            try:
                await ctx.bot.send_message(
                    chat_id=cid,
                    parse_mode="Markdown",
                    disable_web_page_preview=True,
                    text=(
                        f"🌟 *Пятница — время якорного брата*\n\n"
                        f"Напиши {pn} прямо сейчас:\n\n"
                        f"«Как прошла твоя неделя, брат?\n"
                        f"Что выполнил? Что было трудно?»\n\n"
                        f"🤲 И сделай дуа за него по имени.\n\n"
                        f"🌿 _Связь — это и есть умма_"
                    ),
                    reply_markup=InlineKeyboardMarkup([[
                        InlineKeyboardButton("✉️ Написать", url=f"tg://user?id={pid}"),
                        InlineKeyboardButton("📊 Мой прогресс", callback_data="my_prog"),
                    ]])
                )
                count += 1
            except Exception as e:
                logger.warning(f"Friday checkin → {cid}: {e}")
    if count:
        logger.info(f"Пятничный чек-ин якорных братьев: {count} сообщений")


# ══════════════════════════════════════════════════════════════════
#  ЭТАП 9 — ОНБОРДИНГ
# ══════════════════════════════════════════════════════════════════

async def run_onboarding(bot, user_id: int, name: str, level: str, week: int,
                         ctx: ContextTypes.DEFAULT_TYPE):
    """Запускает полный онбординг после активации участника."""
    first = name.split()[0] if name else "Брат"

    # ── Сообщение 1: тёплое приветствие ─────────────────────────
    await bot.send_message(
        chat_id=user_id,
        parse_mode="Markdown",
        text=(
            f"🌿 *БисмиЛлях, {first}!*\n\n"
            f"Ты вступил в программу *IQ Barakah*.\n\n"
            f"Это не просто курс. Это путь — к себе, к Аллаху, к своему наследию.\n\n"
            f"Аллах ﷻ сказал:\n"
            f"_«Поистине, Аллах не меняет положение народа, пока они сами не изменят то, что в них»_ (Ар-Ра'd, 11)\n\n"
            f"Ты уже сделал шаг. Это и есть начало изменений."
        )
    )

    # ── Сообщение 2: как работает программа ─────────────────────
    level_name  = LEVEL_NAMES[level]
    total_weeks = LEVEL_WEEKS[level]
    await bot.send_message(
        chat_id=user_id,
        parse_mode="Markdown",
        text=(
            f"📋 *Как работает программа*\n\n"
            f"📍 *Твой путь:* {level_name}\n"
            f"📅 *{total_weeks} недель* — один урок каждый понедельник в 9:00\n\n"
            f"*Что тебя ждёт каждую неделю:*\n"
            f"🌅 Утро — азкар и намерение\n"
            f"📖 Урок понедельника — тема + 3 задания\n"
            f"🌙 Вечер — мухасаба: что сделал, что упустил\n"
            f"🤝 Пятница — чек-ин с якорным братом\n"
            f"📞 Пятница 14:00 — живой созвон с основателем IQ Barakah\n\n"
            f"🌿 _Маленький шаг каждый день — это и есть барakat_"
        ),
        reply_markup=InlineKeyboardMarkup([
            [InlineKeyboardButton("🔔 Включить напоминания", callback_data="onb_reminders")],
            [InlineKeyboardButton("📱 Открыть карту пути", web_app=WebAppInfo(url=MINIAPP_URL))],
        ])
    )

    # ── Сообщение 3: письмо себе будущему ───────────────────────
    await bot.send_message(
        chat_id=user_id,
        parse_mode="Markdown",
        text=(
            "✍️ *Письмо себе будущему*\n\n"
            "Прямо сейчас — напиши несколько слов себе будущему.\n\n"
            "Что хочешь изменить? Чего хочешь достичь? "
            "Каким человеком хочешь стать?\n\n"
            "Я сохраню это письмо и верну тебе в конце программы. "
            "Ты увидишь кем ты был — и кем стал. 📜\n\n"
            "_Напиши прямо сейчас — любое количество слов._"
        ),
        reply_markup=InlineKeyboardMarkup([[
            InlineKeyboardButton("⏭️ Пропустить", callback_data="letter_skip"),
        ]])
    )
    # Установить флаг ожидания письма
    ctx.bot_data.setdefault("pending_letter", {})[str(user_id)] = True

    # ── Сообщение 4: выбор уровня (ВАКТ) или первый урок ────────
    entry = ctx.bot_data.get("active_users", {}).get(str(user_id), {})
    if not entry:
        entry = {"level": level, "week": week, "name": name}

    if level == "А":
        # Если пользователь уже проходил диагностику — берём результат автоматически
        uid_str = str(user_id)
        diag_level = ctx.bot_data.get("user_diag_level", {}).get(uid_str) if ctx else None
        if diag_level in ("А", "Б", "В"):
            entry = ctx.bot_data.get("active_users", {}).get(uid_str)
            if entry:
                entry["vakt_level"] = diag_level
            labels = {"А": "🌱 Уровень А", "Б": "📗 Уровень Б", "В": "📘 Уровень В"}
            await bot.send_message(
                chat_id=user_id,
                parse_mode="Markdown",
                text=(
                    f"✅ По результатам диагностики — *{labels[diag_level]}*\n\n"
                    f"БисмиЛлях! Вот твой первый урок 👇"
                )
            )
            await send_week_lesson(bot, user_id, entry, ctx=None)
        else:
            # Для ВАКТ — выбор уровня вручную
            await bot.send_message(
                chat_id=user_id,
                parse_mode="Markdown",
                text=(
                    "🌱 *Последний шаг — выбери свой уровень*\n\n"
                    "Это не экзамен. Просто честно ответь себе где ты сейчас:\n\n"
                    "🌱 *Уровень А* — я этнический мусульманин, "
                    "практикую редко или совсем не практикую. "
                    "Хочу начать с малого, без давления.\n\n"
                    "📗 *Уровень Б* — я молюсь, но только фард-намазы. "
                    "Читаю Коран, но не каждый день. Нет системы. "
                    "Хочу выстроить постоянство.\n\n"
                    "📘 *Уровень В* — я практикую регулярно. "
                    "Хочу смиренности, искренности, глубины — "
                    "передача знаний, наследие.\n\n"
                    "Или пройди диагностику — мы определим уровень сами 👇"
                ),
                reply_markup=InlineKeyboardMarkup([
                    [InlineKeyboardButton("🌱 Уровень А — начинаю с нуля",   callback_data="vakt_level_А")],
                    [InlineKeyboardButton("📗 Уровень Б — хочу постоянство", callback_data="vakt_level_Б")],
                    [InlineKeyboardButton("📘 Уровень В — хочу глубины",     callback_data="vakt_level_В")],
                    [InlineKeyboardButton("🔍 Пройти диагностику уровня",    callback_data="vakt_level_diag")],
                ])
            )
    else:
        await bot.send_message(
            chat_id=user_id,
            parse_mode="Markdown",
            text="📬 *А вот твой первый урок — прямо сейчас:*"
        )
        await send_week_lesson(bot, user_id, entry, ctx=None)

    # ── Запланировать day-2 follow-up (через 24ч) ────────────────
    from datetime import timedelta
    ctx.application.job_queue.run_once(
        _job_onboarding_day2,
        when=timedelta(hours=24),
        data={"uid": user_id, "name": name, "level": level},
        name=f"onb_day2_{user_id}",
    )

    # ── Запланировать day-7 check-in (через 7 дней) ──────────────
    ctx.application.job_queue.run_once(
        _job_onboarding_day7,
        when=timedelta(days=7),
        data={"uid": user_id, "name": name, "level": level},
        name=f"onb_day7_{user_id}",
    )


async def _job_onboarding_day2(ctx: ContextTypes.DEFAULT_TYPE):
    """Через 24ч после активации — мягкий follow-up."""
    data  = ctx.job.data
    uid   = data["uid"]
    first = data["name"].split()[0] if data.get("name") else "Брат"
    try:
        await ctx.bot.send_message(
            chat_id=uid,
            parse_mode="Markdown",
            text=(
                f"🌅 *{first}, как прошёл первый день?*\n\n"
                f"Вчера начался твой путь. Небольшой вопрос:\n\n"
                f"✅ Ты прочитал урок?\n"
                f"✅ Сделал хотя бы одно задание?\n"
                f"✅ Включил напоминания?\n\n"
                f"Не нужно делать всё сразу. Одно действие — уже баракат.\n\n"
                f"🌿 _«Самое любимое дело для Аллаха — то, что делается постоянно, даже если оно мало»_ (Бухари)"
            ),
            reply_markup=InlineKeyboardMarkup([
                [InlineKeyboardButton("✅ Да, всё сделал",      callback_data="onb_done_yes")],
                [InlineKeyboardButton("🔄 Ещё не успел",        callback_data="onb_done_no")],
                [InlineKeyboardButton("🔔 Включить напоминания", callback_data="onb_reminders")],
            ])
        )
    except Exception as e:
        logger.warning(f"Онбординг day2 → {uid}: {e}")


